        "很多人第一次理解银行,会把银行想成一个巨大的保险柜:大家把钱放进去,银行替大家保管。这个想象只对了一小部分。现代银行更像一张资产负债表:它一边欠储户钱,一边把钱贷给别人;一边提供支付便利,一边承担信用和流动性风险。央行也不是遥控所有资产涨跌的按钮,它更像金融系统的水位调节器。",
