        "很多普通人不是直接买几十只股票和债券,而是买基金。基金看起来只是一个产品名称,其实它背后是一套法律结构、账户安排、投资规则和费用机制。你买基金,不是把钱交给一个黑箱祈祷它涨,而是买入一套约定:谁来管钱、可以买什么、怎么估值、怎么收费、风险由谁承担。",
