                    "举个例子。某公司有 1 亿股流通股,今天成交 1000 万股,换手率就是 10%。这不代表 10% 的人都换了,因为同一股可能一天里被多次买卖;也不代表剩下 90% 完全不关心,只是没有形成交易。"
