                    "对量化来说,复权是基础但很容易犯错。用未复权价格计算收益,可能把分红除权当成下跌;用前复权价格模拟真实成交,又可能拿到历史上不存在的价格。通常做收益和因子要用复权口径,做成交和订单要用当时真实可交易价格,两者不能混用。"
