                    "读懂市场中性,最后回到三个问题。第一,你的多头为什么会跑赢空头? 这需要因子和模型证明。第二,你中和了哪些风险,还剩哪些风险? 这需要风险模型和归因。第三,对冲和交易成本之后还剩多少? 这需要真实成本和容量估计。"
