        "金融资料很多,质量差异也很大。券商研报可能有启发,学术论文可能严谨,基金月报可能贴近产品,网络文章可能通俗。但无论来源多权威,你都不能只看结论。读量化资料的顺序应该是: 它研究什么问题,用了什么数据,有没有未来函数,基准是什么,成本怎么扣,样本外如何,结论能不能交易。",
