        "模拟盘不是玩具。它把回测里的历史循环变成真实时间里的流程。周一数据迟到,周二信号文件为空,周三某只股票停牌,周四成本比假设高,周五你要写复盘。第一次跑模拟盘,目标不是赚钱,而是发现系统在真实节奏下会出哪些问题。",
